SINA_SMART["embryo1-gastrulation"] = {"lecture":"embryo1-gastrulation","title":"Gastrulation and neurulation","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"embryo1-gastrulation:e0","text":"Periods: germinal, embryonic (to week 8), fetal (week 9 to birth).","topic":"Periods and events of embryogenesis","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e1","text":"Gastrulation (week 3): three germ layers; first sign: primitive streak.","topic":"Gastrulation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e2","text":"Primitive node and pit at the cranial end; axes fixed.","topic":"Gastrulation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e3","text":"Invaginating epiblast forms endoderm then mesoderm; the rest is ectoderm.","topic":"Gastrulation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e4","text":"Oropharyngeal and cloacal membranes stay bilaminar.","topic":"Gastrulation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e5","text":"Sacrococcygeal teratoma: streak remnant, commonest newborn tumour.","topic":"Gastrulation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e6","text":"Notochord: axis, rigidity, induces neural plate, nucleus pulposus.","topic":"The notochord","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e7","text":"Neural plate → folds → groove → tube (CNS).","topic":"Neurulation and the neural crest","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e8","text":"Neuropores close ~day 25 (cranial) and ~day 28 (caudal).","topic":"Neurulation and the neural crest","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e9","text":"Neural crest: ganglia, Schwann cells, melanocytes, adrenal medulla, facial skeleton.","topic":"Neurulation and the neural crest","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gastrulation:e10","text":"Anencephaly (cranial) and spina bifida (caudal) = neural tube defects.","topic":"Clinical correlates","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"og80za":"a","zd0ozs":"a","19st436":"a","rcd4xz":"a","1y53sfy":"a","1rvgt6s":"a","12sg7my":"a","1t8j5gc":"a","gw6ylb":"a","1wt221q":"a","xjaety":"a","1lr5nyl":"a","bc2ll0":"a","y6d3tu":"a","170vlp1":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"embryo1-gastrulation:e0":{"s":0,"u":["Periods: germinal, embryonic (to week 8), fetal (week 9 to birth).","The antenatal period has three parts: germinal (fertilisation to implantation), embryonic (implantation to week 8) and fetal (week 9 to birth)."],"dp":[]},"embryo1-gastrulation:e1":{"s":1,"u":["Gastrulation (week 3): three germ layers; first sign: primitive streak.","Gastrulation (week 3) forms the three germ layers and starts morphogenesis .","Its first sign is the primitive streak on the epiblast surface, with a primitive groove , a primitive node at its cranial end and a primitive pit ."],"dp":[]},"embryo1-gastrulation:e2":{"s":1,"u":["Primitive node and pit at the cranial end; axes fixed.","Its first sign is the primitive streak on the epiblast surface, with a primitive groove , a primitive node at its cranial end and a primitive pit ."],"dp":[]},"embryo1-gastrulation:e3":{"s":1,"u":["Invaginating epiblast forms endoderm then mesoderm; the rest is ectoderm.","Epiblast cells invaginate through the streak: the first displace the hypoblast to form the endoderm , the next spread between the layers as mesoderm (mesenchyme: pluripotent embryonic connective tissue), and the epiblast left behind becomes the ectoderm ."],"dp":[]},"embryo1-gastrulation:e4":{"s":1,"u":["Oropharyngeal and cloacal membranes stay bilaminar.","The prechordal plate (a signalling centre with Shh and PAX6 for the forebrain and eyes) and the oropharyngeal and cloacal membranes remain bilaminar."],"dp":[]},"embryo1-gastrulation:e5":{"s":1,"u":["Sacrococcygeal teratoma: streak remnant, commonest newborn tumour.","The streak normally regresses; a remnant can give a sacrococcygeal teratoma , the most common tumour of newborns, a benign germ-cell tumour of pluripotent cells removed surgically early."],"dp":[]},"embryo1-gastrulation:e6":{"s":2,"u":["Notochord: axis, rigidity, induces neural plate, nucleus pulposus.","Functions: defines the axis , gives rigidity , is the primary inducer of the neural plate and the axial musculoskeleton, and contributes to the intervertebral discs (nucleus pulposus)."],"dp":[]},"embryo1-gastrulation:e7":{"s":3,"u":["Neural plate → folds → groove → tube (CNS).","Neurulation : the ectoderm over the notochord thickens into the neural plate ; its edges rise as neural folds around the neural groove , then fuse into the neural tube , the future brain and spinal cord."],"dp":[]},"embryo1-gastrulation:e8":{"s":3,"u":["Neuropores close ~day 25 (cranial) and ~day 28 (caudal).","The neuropores close last (cranial around day 25, caudal around day 28)."],"dp":[]},"embryo1-gastrulation:e9":{"s":3,"u":["Neural crest: ganglia, Schwann cells, melanocytes, adrenal medulla, facial skeleton.","Neural crest cells leave the fold edges and migrate: connective tissue and bones of the face and skull, cranial, spinal and autonomic ganglia, heart septum, odontoblasts, dermis of face and neck, adrenal medulla , Schwann cells , glia, meninges, melanocytes , smooth muscle of some vessels."],"dp":[]},"embryo1-gastrulation:e10":{"s":4,"u":["Anencephaly (cranial) and spina bifida (caudal) = neural tube defects.","Neural tube defects : anencephaly (failure to close cranially) and spina bifida (failure to close anywhere from cervical to lumbar region), graded as spina bifida occulta (hair tuft), meningocele and myelomeningocele, which can paralyse the lower limbs."],"dp":[{"h":"Folic acid and the 28-day window","t":"The neural tube closes by about day 28 after fertilisation, often before a woman knows she is pregnant. Folate is needed for the rapid DNA synthesis of the folding neuroepithelium, and adequate folate before and early in pregnancy greatly lowers the risk of anencephaly and spina bifida. Because closure is complete so early, supplements must start before conception ; starting at the first antenatal visit is often too late. Open defects also leak alpha-fetoprotein, which is why a raised AFP in maternal serum or amniotic fluid prompts a detailed scan. Source: the lecture's neuropore timing; public-health folate guidance."}]}},"meta":{"og80za":{"a":"recall","vg":"embryo1-gastrulation:e1/recall/1"},"zd0ozs":{"a":"recall","vg":"embryo1-gastrulation:e1/recall/2"},"19st436":{"a":"recall","vg":"embryo1-gastrulation:e2/recall/1"},"rcd4xz":{"a":"recall","vg":"embryo1-gastrulation:e3/recall/1"},"1y53sfy":{"a":"recall","vg":"embryo1-gastrulation:e4/recall/1"},"1rvgt6s":{"a":"recall","vg":"embryo1-gastrulation:e5/recall/1"},"12sg7my":{"a":"recall","vg":"embryo1-gastrulation:e6/recall/1"},"1t8j5gc":{"a":"recall","vg":"embryo1-gastrulation:e6/recall/2"},"gw6ylb":{"a":"recall","vg":"embryo1-gastrulation:e7/recall/1"},"1wt221q":{"a":"recall","vg":"embryo1-gastrulation:e9/recall/1"},"xjaety":{"a":"recall","vg":"embryo1-gastrulation:e9/recall/2"},"1lr5nyl":{"a":"recall","vg":"embryo1-gastrulation:e10/recall/1"},"bc2ll0":{"a":"recall","vg":"embryo1-gastrulation:e0/recall/1"},"y6d3tu":{"a":"recall","vg":"embryo1-gastrulation:e0/recall/1"},"170vlp1":{"a":"recall","vg":"embryo1-gastrulation:e4/recall/2"}},"explRev":"279540c63bc2"};
